-- Consolidated schema script for the household-items app (MySQL / MariaDB).
--
-- Generated by folding every Doctrine migration in this folder, in version
-- order, into a single script. The Doctrine migrations themselves were written
-- with the SQLite platform (CLOB / DATETIME, temp-table rebuilds for ALTERs), so
-- the statements below are translated to MySQL/MariaDB syntax; the resulting
-- schema is equivalent.
--
-- Intended for a database at the pre-migration baseline (or empty). It creates
-- the original tables and then applies each later change in order.
--
-- Transient steps that a single script does not need are folded away:
--   * items.image_url (added by Version20260728134019, dropped by Version20260731092641)
--   * request_response_log.requested_at (added by Version20260913120000, dropped by Version20260913130000)
--   * users.password (created by Version20260728125208, dropped by Version20261101130000)
--   * the single-column unique index on users.email (replaced by the composite one)


-- ===========================================================================
-- Version20260728125208 - Create users and items tables
-- ===========================================================================
CREATE TABLE items (
    id VARCHAR(255) NOT NULL,
    user_id VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    description LONGTEXT NOT NULL,
    status VARCHAR(255) NOT NULL,
    image_filename VARCHAR(255) NOT NULL DEFAULT '',
    PRIMARY KEY (id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE INDEX IDX_E11EE94DA76ED395 ON items (user_id);

-- users.password is created here and dropped at the end of the script, when
-- login switches to email one-time codes (Version20261101130000).
CREATE TABLE users (
    id VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL,
    password VARCHAR(255) NOT NULL,
    contact_info VARCHAR(255) NOT NULL,
    group_id VARCHAR(255) NOT NULL,
    PRIMARY KEY (id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE UNIQUE INDEX UNIQ_1483A5E9E7927C74 ON users (email);
CREATE INDEX IDX_1483A5E9FE54D947 ON users (group_id);


-- ===========================================================================
-- Version20260728134019 / Version20260731092641 - items.image_url added then
-- dropped; folded away, the column does not exist in the final schema.
-- ===========================================================================


-- ===========================================================================
-- Version20260729101500 - Create user_groups and link users.group_id (FK)
-- ===========================================================================
CREATE TABLE user_groups (
    id VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    PRIMARY KEY (id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

ALTER TABLE users
    ADD CONSTRAINT FK_1483A5E9FE54D947 FOREIGN KEY (group_id) REFERENCES user_groups (id);


-- ===========================================================================
-- Version20260729110000 - users are unique per (email, group_id)
-- ===========================================================================
DROP INDEX UNIQ_1483A5E9E7927C74 ON users;
CREATE UNIQUE INDEX uniq_users_email_group ON users (email, group_id);


-- ===========================================================================
-- Version20260729120000 - created_at on users, items and user_groups
-- (new rows get the value from the entities' PrePersist hook)
-- ===========================================================================
ALTER TABLE users
    ADD COLUMN created_at DATETIME NOT NULL DEFAULT '1970-01-01 00:00:00';
UPDATE users SET created_at = CURRENT_TIMESTAMP;

ALTER TABLE items
    ADD COLUMN created_at DATETIME NOT NULL DEFAULT '1970-01-01 00:00:00';
UPDATE items SET created_at = CURRENT_TIMESTAMP;

ALTER TABLE user_groups
    ADD COLUMN created_at DATETIME NOT NULL DEFAULT '1970-01-01 00:00:00';
UPDATE user_groups SET created_at = CURRENT_TIMESTAMP;


-- ===========================================================================
-- Version20260913060914 - Create the append-only event_log table
-- ===========================================================================
CREATE TABLE event_log (
    id VARCHAR(255) NOT NULL,
    event_name VARCHAR(255) NOT NULL,
    aggregate_type VARCHAR(255) NOT NULL,
    aggregate_id VARCHAR(255) NOT NULL,
    payload LONGTEXT NOT NULL,
    actor_id VARCHAR(255) DEFAULT NULL,
    occurred_at DATETIME NOT NULL,
    recorded_at DATETIME NOT NULL,
    PRIMARY KEY (id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE INDEX idx_event_log_aggregate ON event_log (aggregate_type, aggregate_id);
CREATE INDEX idx_event_log_event_name ON event_log (event_name);
CREATE INDEX idx_event_log_occurred_at ON event_log (occurred_at);
CREATE INDEX idx_event_log_actor_id ON event_log (actor_id);


-- ===========================================================================
-- Version20260913120000 / Version20260913130000 / Version20260913140000 -
-- Create request_response_log (requested_at added then dropped; responded_at
-- mandatory in the final schema)
-- ===========================================================================
CREATE TABLE request_response_log (
    id VARCHAR(255) NOT NULL,
    method VARCHAR(255) NOT NULL,
    route VARCHAR(255) DEFAULT NULL,
    uri LONGTEXT NOT NULL,
    ip VARCHAR(255) DEFAULT NULL,
    request_payload LONGTEXT NOT NULL,
    response_payload LONGTEXT DEFAULT NULL,
    status INT DEFAULT NULL,
    content_type VARCHAR(255) DEFAULT NULL,
    content_length INT DEFAULT NULL,
    duration_ms INT DEFAULT NULL,
    responded_at DATETIME NOT NULL,
    PRIMARY KEY (id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE INDEX idx_request_response_log_method ON request_response_log (method);
CREATE INDEX idx_request_response_log_status ON request_response_log (status);


-- ===========================================================================
-- Version20261101120000 - Create login_otp (email one-time login codes)
-- ===========================================================================
CREATE TABLE login_otp (
    id VARCHAR(36) NOT NULL,
    email VARCHAR(180) NOT NULL,
    group_id VARCHAR(36) NOT NULL,
    hashed_code VARCHAR(255) NOT NULL,
    expires_at DATETIME NOT NULL,
    created_at DATETIME NOT NULL,
    used_at DATETIME DEFAULT NULL,
    PRIMARY KEY (id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE INDEX idx_login_otp_lookup ON login_otp (email, group_id);


-- ===========================================================================
-- Version20261101130000 - Login is email + one-time code, users lose password
-- ===========================================================================
ALTER TABLE users DROP COLUMN password;
